INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Gastroenterology','Pathology','Oesophageal Disease','easy','flashcard','What type of epithelium defines Barrett''s oesophagus and what is its clinical significance?','["Specialised intestinal columnar metaplasia with goblet cells replacing squamous epithelium; predisposes to oesophageal adenocarcinoma at ~0.5% per year."]','A','Barrett''s oesophagus results from chronic GORD causing replacement of the normal stratified squamous epithelium with specialised intestinal-type columnar mucosa (goblet cells). It is the main precursor for oesophageal adenocarcinoma and warrants endoscopic surveillance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Barrett Esophagus, p.757'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Oesophageal Disease','medium','flashcard','What is the pathological mechanism of achalasia, and what is the classic barium appearance?','["Loss of ganglion cells in Auerbach''s myenteric plexus → failure of LOS relaxation and aperistalsis; barium shows ''bird-beak'' tapering at the LOS with proximal oesophageal dilatation."]','A','Achalasia results from immune-mediated or idiopathic destruction of inhibitory (VIP/NO-releasing) neurons in Auerbach''s plexus. The resulting LOS hypertonia and aperistalsis cause progressive dysphagia and regurgitation. Treatment: pneumatic dilation or Heller myotomy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Achalasia, p.753'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Oesophageal Disease','easy','flashcard','What are the risk factors for oesophageal squamous cell carcinoma?','["Smoking, alcohol, hot beverage consumption, nitrosamines, achalasia, Plummer-Vinson syndrome, nutritional deficiencies (vitamins A, C, zinc); upper/middle two-thirds of oesophagus."]','A','SCC arises from native squamous epithelium in the upper and middle oesophagus. It is most common in regions with high tobacco/alcohol use and hot beverage consumption (e.g., parts of Africa, Asia). Incidence is higher in Black males.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Squamous Cell Carcinoma, p.759'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Oesophageal Disease','medium','flashcard','What is the difference between a Mallory-Weiss tear and Boerhaave syndrome?','["Mallory-Weiss: mucosal (partial-thickness) longitudinal tear at the GEJ from retching; Boerhaave syndrome: full-thickness oesophageal perforation from forceful vomiting (surgical emergency)."]','A','Mallory-Weiss tears account for ~10-15% of upper GI bleeds and typically occur in alcoholics after repeated retching. Most stop bleeding spontaneously. Boerhaave syndrome carries ~30% mortality and presents with Mackler''s triad: vomiting, chest pain, and subcutaneous emphysema.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Lacerations, p.754'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Oesophageal Disease','hard','flashcard','Name the molecular steps in the progression of Barrett''s oesophagus to adenocarcinoma.','["p16 (CDKN2A) loss (early) → TP53 mutation → chromosomal instability and aneuploidy → invasive adenocarcinoma."]','A','The Barrett''s-to-adenocarcinoma sequence differs from the colorectal APC-KRAS-TP53 pathway. Early p16 loss allows cell cycle deregulation; TP53 mutation then drives malignant transformation. CDX2 expression drives intestinal differentiation of Barrett''s epithelium.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Adenocarcinoma, p.758'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Oesophageal Disease','easy','flashcard','At which anatomical site does oesophageal adenocarcinoma most commonly arise and what is the predisposing condition?','["Lower third of the oesophagus/GEJ, arising from Barrett''s oesophagus (intestinal metaplasia) caused by chronic GORD."]','A','Oesophageal adenocarcinoma has a dramatically rising incidence in Western countries, strongly associated with obesity and GORD. It arises from Barrett''s metaplasia through a dysplasia-carcinoma sequence. Endoscopic screening of Barrett''s patients targets dysplastic foci.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Adenocarcinoma, p.758'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Oesophageal Disease','medium','flashcard','What are the histological features of reflux oesophagitis on oesophageal biopsy?','["Basal cell hyperplasia (>20% of epithelial thickness), elongation of lamina propria papillae (>66% depth), intraepithelial eosinophilia, and dilated intercellular spaces."]','A','These changes reflect repetitive acid-peptic injury to the squamous epithelium. Increased mitotic activity in the basal layer drives hyperplasia. Intraepithelial eosinophils (not goblet cells) reflect acid-induced inflammation. Finding goblet cells instead indicates Barrett''s metaplasia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Reflux Esophagitis, p.755'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Oesophageal Disease','easy','flashcard','What is a Zenker''s diverticulum and through which anatomical weakness does it herniate?','["A pulsion (false) diverticulum of the posterior pharyngeal wall herniated through Killian''s dehiscence (between thyropharyngeus and cricopharyngeus muscles); presents with dysphagia, regurgitation, and halitosis."]','A','Zenker''s diverticulum is the most common oesophageal diverticulum, occurring in older adults. It is a false diverticulum (contains only mucosa and submucosa) and forms due to incomplete relaxation of the cricopharyngeus muscle creating a high-pressure zone. Regurgitated food may be retained within it.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Esophageal Obstruction, p.753'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Oesophageal Disease','hard','flashcard','How does the epidemiology of oesophageal SCC differ from adenocarcinoma?','["SCC: upper/middle oesophagus, more common in Black males, declining in incidence, associated with smoking/alcohol/hot beverages/nutritional deficiency. Adenocarcinoma: lower oesophagus/GEJ, rising incidence, more common in White males, associated with GORD/obesity/Barrett''s."]','A','The epidemiological shift from SCC to adenocarcinoma as the dominant oesophageal cancer in Western countries reflects rising rates of obesity and GORD. SCC remains predominant in parts of Asia, Africa, and among populations with high alcohol/tobacco use.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Oesophageal Tumors, p.758-759'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Oesophageal Disease','medium','flashcard','What is the significance of oesophageal varices and how do they form?','["Oesophageal varices are dilated submucosal veins at the lower oesophagus forming from portosystemic collateral flow (via left gastric vein) in portal hypertension; rupture causes life-threatening haemorrhage with 20-30% mortality per episode."]','A','In portal hypertension (from cirrhosis), elevated portal pressure drives blood through the left gastric (coronary) vein into the oesophageal venous plexus. These subepithelial varices are prone to rupture from acid reflux or Valsalva manoeuvre. Prophylaxis with beta-blockers or banding reduces re-bleeding risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Esophageal Varices, p.756'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Gastric Disease','easy','flashcard','How is H. pylori infection diagnosed and what diseases does it cause?','["Diagnosed by: urea breath test, stool antigen test, CLO test, or histology (Giemsa stain). Causes: chronic antral gastritis, peptic ulcer disease (duodenal > gastric), MALT lymphoma, and gastric adenocarcinoma."]','A','H. pylori is a Gram-negative urease-positive curved rod that colonises the gastric antrum. It evades gastric acid using urease (ammonia production) and adhesins. Over 50% of the global population is infected. Eradication with triple therapy (PPI + amoxicillin + clarithromycin) heals most PUD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Helicobacter pylori Gastritis, p.763'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Gastric Disease','medium','flashcard','What are the Lauren classification types of gastric adenocarcinoma and how do they differ?','["Intestinal type: gland-forming, associated with H. pylori/atrophic gastritis/intestinal metaplasia (Correa cascade), better prognosis, common in older males. Diffuse type: signet ring cells, CDH1 loss, linitis plastica, worse prognosis, younger patients."]','A','The Lauren classification divides gastric adenocarcinoma into intestinal and diffuse types. The intestinal type follows the Correa cascade (H. pylori → atrophic gastritis → intestinal metaplasia → dysplasia → carcinoma). The diffuse type infiltrates without forming glands, producing linitis plastica (leather-bottle stomach) with peritoneal seeding.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Gastric Adenocarcinoma, p.771'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Gastric Disease','easy','flashcard','What is the relationship between H. pylori and gastric MALT lymphoma?','["H. pylori drives chronic antigen-stimulated B-cell proliferation in the gastric mucosa, producing low-grade MALT lymphoma. Eradication of H. pylori leads to regression in ~75% of low-grade cases."]','A','Gastric MALT (mucosa-associated lymphoid tissue) lymphoma is a marginal zone B-cell lymphoma dependent on H. pylori-specific T-cell help for B-cell stimulation. Removing the antigen (H. pylori eradication) eliminates this drive. High-grade cases or those with t(11;18) translocation require chemotherapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Lymphoma, p.773'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Gastric Disease','hard','flashcard','Describe the Correa cascade of gastric carcinogenesis.','["H. pylori infection → chronic superficial gastritis → atrophic gastritis → intestinal metaplasia → dysplasia → intestinal-type gastric adenocarcinoma."]','A','The Correa cascade is a well-defined multistep progression that takes decades. H. pylori infection is the initiating event. Atrophic gastritis reduces acid secretion, allowing bacterial overgrowth and nitrosamine formation. Intestinal metaplasia is a premalignant state. Eradication of H. pylori at early stages may arrest progression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Gastric Adenocarcinoma, p.771'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Gastric Disease','medium','flashcard','What is the mechanism of peptic ulcer formation in H. pylori infection?','["H. pylori colonises the antrum → stimulates gastrin release → increased acid output → impairs mucosal prostaglandin defence → duodenal/gastric ulceration. CagA+ strains cause more virulent disease via disruption of tight junctions and cytokine induction."]','A','H. pylori causes ulcers via direct cytotoxicity (VacA cytotoxin), induction of mucosal inflammation (IL-8, neutrophil recruitment), increased acid secretion from antral gastrin release, and impairment of mucosal defences. Triple therapy eradicating H. pylori achieves >90% ulcer healing and recurrence prevention.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Peptic Ulcer Disease, p.766'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Gastric Disease','easy','flashcard','What is autoimmune gastritis and what is its main complication?','["T-cell-mediated autoimmune destruction of gastric parietal cells in the body/fundus; antibodies against parietal cells and intrinsic factor → achlorhydria and pernicious anaemia (vitamin B12 deficiency)."]','A','Autoimmune gastritis (Type A gastritis) affects the body and fundus, sparing the antrum. Loss of parietal cells causes achlorhydria and intrinsic factor deficiency, impairing ileal B12 absorption. Patients present with megaloblastic anaemia, neurological symptoms (subacute combined degeneration of the cord), and are at increased risk of gastric carcinoid tumours and adenocarcinoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Autoimmune Gastritis, p.764'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Gastric Disease','medium','flashcard','What are the macroscopic features of signet ring cell (diffuse-type) gastric adenocarcinoma?','["Diffuse infiltration of the gastric wall by signet ring cells (mucin-filled, nucleus pushed to periphery) causing linitis plastica — a rigid, shrunken, leather-bottle stomach without discrete mass formation."]','A','Linitis plastica results from signet ring cell infiltration thickening all layers of the gastric wall, obliterating the rugal folds and reducing gastric compliance. It presents with early satiety, weight loss, and dysphagia. It is associated with CDH1 (E-cadherin) germline mutations in hereditary diffuse gastric cancer.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Gastric Adenocarcinoma, p.771'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Gastric Disease','hard','flashcard','What is Zollinger-Ellison syndrome and what is its association with MEN1?','["Zollinger-Ellison syndrome: gastrinoma (gastrin-secreting tumour) causing massive acid hypersecretion, multiple refractory peptic ulcers often in unusual locations, and diarrhoea. ~25% are associated with MEN1 (multiple endocrine neoplasia type 1 — parathyroid, pituitary, pancreatic tumours)."]','A','Gastrinomas are most commonly found in the gastrinoma triangle (duodenum, pancreatic head, porta hepatis). High fasting serum gastrin (>1000 pg/mL) and positive secretin stimulation test are diagnostic. PPI therapy controls symptoms; surgical resection is curative if localised.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Zollinger-Ellison Syndrome, p.769'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Gastric Disease','easy','flashcard','What are the features of Ménétrier''s disease?','["Giant rugal folds in the gastric body, protein-losing gastropathy (hypoalbuminaemia, oedema), hypochlorhydria; associated with TGF-α overexpression; increased risk of gastric cancer."]','A','Ménétrier''s disease is a rare hypertrophic gastropathy causing foveolar hyperplasia (elongation of mucous neck cells) and replacement of parietal cells, resulting in protein loss through the mucosa and reduced acid secretion. It can respond to anti-EGF receptor therapy (cetuximab) as TGF-α activates the EGF receptor.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Ménétrier Disease, p.768'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Gastric Disease','medium','flashcard','How do NSAID-induced ulcers differ from H. pylori-induced ulcers clinically?','["NSAID ulcers: often asymptomatic until complicated (bleed/perforate), predominantly gastric, caused by COX-1 inhibition reducing mucosal prostaglandins, occur without H. pylori. H. pylori ulcers: symptomatic (epigastric pain), predominantly duodenal, caused by acid hypersecretion and mucosal defence impairment."]','A','NSAIDs inhibit COX-1 (constitutive), reducing PGE2 and PGI2 synthesis, impairing mucus/bicarbonate secretion and mucosal blood flow. Selective COX-2 inhibitors reduce GI risk but increase cardiovascular risk. Concurrent PPI therapy with NSAIDs reduces ulcer complications.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Peptic Ulcer Disease, p.766'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Coeliac Disease and Malabsorption','easy','flashcard','What are the classic serological markers of coeliac disease and what is the gold-standard diagnostic test?','["Anti-tissue transglutaminase IgA (anti-TTG IgA) most sensitive/specific; anti-endomysial IgA most specific. Gold standard: duodenal biopsy showing villous atrophy with increased intraepithelial lymphocytes and crypt hyperplasia."]','A','Anti-TTG IgA should be measured with total serum IgA to detect IgA deficiency. Biopsy remains mandatory for diagnosis before commencing a gluten-free diet. The Marsh grading system (1-4) grades histological severity. Clinical and histological response to a gluten-free diet confirms the diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Celiac Disease, p.782'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Coeliac Disease and Malabsorption','medium','flashcard','Describe the histological changes of coeliac disease and the Marsh grading system.','["Marsh 1: increased intraepithelial lymphocytes (IEL) >25/100 enterocytes. Marsh 2: + crypt hyperplasia. Marsh 3: + villous atrophy (3a partial, 3b subtotal, 3c total). Marsh 4: total villous atrophy with crypt hypoplasia (rare)."]','A','The Marsh classification grades severity from increased IELs alone (early disease/latent coeliac) through partial to total villous atrophy. Severity correlates with symptom burden. Even Marsh 1 changes in the right clinical and serological context may warrant gluten-free diet trial.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Celiac Disease, p.782'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Coeliac Disease and Malabsorption','easy','flashcard','Which HLA types are associated with coeliac disease and how do they contribute to pathogenesis?','["HLA-DQ2 (~90%) and HLA-DQ8 (~10%); they present deamidated gliadin peptides (modified by tissue transglutaminase 2) to CD4+ T cells, driving an inflammatory response causing villous atrophy."]','A','The HLA class II molecules HLA-DQ2 and HLA-DQ8 are necessary but not sufficient for coeliac disease — ~30% of the population carries them without developing disease. Environmental triggers and the gut microbiome likely contribute to initiating the immune response in susceptible individuals.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Celiac Disease, p.782'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Coeliac Disease and Malabsorption','hard','flashcard','What is the role of tissue transglutaminase 2 (TG2) in coeliac pathogenesis?','["TG2 deamidates gliadin peptides (converts glutamine → glutamate), greatly increasing their affinity for HLA-DQ2/DQ8, amplifying the CD4+ T-cell immune response. TG2 is also the target autoantigen of anti-endomysial and anti-TTG antibodies."]','A','The deamidated gliadin peptides are presented by HLA-DQ2/DQ8 on dendritic cells to gliadin-specific CD4+ T cells in the lamina propria, which release pro-inflammatory cytokines (IFN-γ). This leads to intraepithelial lymphocyte activation and enterocyte damage causing villous atrophy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Celiac Disease, p.782'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Coeliac Disease and Malabsorption','medium','flashcard','What is dermatitis herpetiformis and its relationship to coeliac disease?','["Dermatitis herpetiformis (DH) is a blistering skin condition associated with coeliac disease, characterised by granular IgA deposits in the dermal papillae on DIF; presents with intensely pruritic vesicles on extensor surfaces; responds to gluten-free diet."]','A','DH occurs in ~10% of coeliac patients and may precede or occur without obvious GI symptoms. The IgA deposits (directed against epidermal transglutaminase/TG3) form immune complexes that activate complement and cause neutrophil recruitment, leading to subepidermal blistering. Dapsone provides rapid symptom relief.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Celiac Disease, p.782'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Coeliac Disease and Malabsorption','easy','flashcard','What are the complications of long-standing coeliac disease?','["Enteropathy-associated T-cell lymphoma (EATL), small bowel adenocarcinoma (jejunum), hyposplenism, osteoporosis (from calcium/vitamin D malabsorption), and iron deficiency anaemia."]','A','EATL arises from intraepithelial T-lymphocytes and typically presents in the jejunum. Refractory coeliac disease type II (with clonal IEL population) is a pre-EATL state. Compliance with a gluten-free diet reduces — but does not eliminate — the risk of lymphoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Celiac Disease, p.782'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Coeliac Disease and Malabsorption','medium','flashcard','Why is the proximal small intestine most severely affected in coeliac disease?','["The proximal small intestine (duodenum and proximal jejunum) is the first segment to encounter dietary gluten after gastric digestion; maximum antigen exposure here drives the greatest immune response and villous atrophy."]','A','This proximal-to-distal gradient of injury means nutrient absorption (iron, folate, calcium in the duodenum; fat-soluble vitamins in the proximal jejunum) is most impaired. Standard diagnostic biopsies are taken from D2 (at least 4 samples) to sample the most affected area.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Celiac Disease, p.782'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Coeliac Disease and Malabsorption','hard','flashcard','What is Whipple''s disease and how is it distinguished from coeliac disease on biopsy?','["Whipple''s disease: caused by Tropheryma whipplei; PAS-positive macrophages in the lamina propria (not villous atrophy); presents with malabsorption, arthralgia, lymphadenopathy, and neurological symptoms. Coeliac: villous atrophy with increased IELs; no PAS-positive macrophages."]','A','Whipple''s disease is rare and predominantly affects middle-aged White males. The PAS-positive macrophages contain bacilli with PAS-reactive glycoproteins. Electron microscopy shows characteristic trilaminar-walled bacilli. Treatment is prolonged antibiotic therapy (ceftriaxone then TMP-SMX for 1 year).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Whipple Disease, p.791'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Coeliac Disease and Malabsorption','easy','flashcard','In which grains is gluten (specifically gliadin) found, and which are safe for coeliac patients?','["Gluten containing — must avoid: wheat, barley, rye (''WBR''). Safe grains: rice, maize/corn, quinoa, millet, and oats (uncontaminated — oats have avenin; tolerated by most but not all coeliac patients)."]','A','Gliadin (from wheat), hordein (barley), and secalin (rye) are the toxic prolamins in coeliac disease. All wheat products including spelt, kamut, semolina, and farro must be avoided. Oats are tolerated by most patients but must be uncontaminated by wheat processing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Celiac Disease, p.782'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Coeliac Disease and Malabsorption','medium','flashcard','What is refractory coeliac disease and what distinguishes type I from type II?','["Refractory coeliac disease: persistent symptoms and villous atrophy despite strict gluten-free diet. Type I: normal IEL phenotype (CD3+CD8+), good prognosis. Type II: aberrant IEL phenotype (CD3+CD8-, CD103+) with monoclonal TCR rearrangement — high risk of EATL; poor prognosis."]','A','Type II refractory coeliac disease represents a clonal intraepithelial lymphoproliferation that is a direct precursor to EATL. Management includes immunosuppression (azathioprine, cladribine) and intensive surveillance. EATL once developed carries a very poor prognosis with 5-year survival <20%.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Celiac Disease, p.782'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Crohn''s Disease','easy','flashcard','What are the classic macroscopic features of Crohn''s disease?','["Skip lesions (discontinuous involvement), transmural inflammation, cobblestoning, rose-thorn ulcers, fistulae, creeping fat (fat wrapping), and fibrous strictures."]','A','Crohn''s disease can affect any part of the GI tract from mouth to anus but most commonly involves the terminal ileum and right colon. The transmural inflammation predisposes to fistula formation (entero-enteric, entero-vesical, entero-cutaneous, perianal) and fibrous strictures causing obstruction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Crohn Disease, p.798'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Crohn''s Disease','medium','flashcard','What histological feature, when present, is virtually pathognomonic of Crohn''s disease?','["Non-caseating (epithelioid) granulomas — present in 30-60% of Crohn''s specimens — occurring in any layer of the bowel wall or in mesenteric lymph nodes."]','A','Granulomas in Crohn''s disease are composed of epithelioid macrophages and giant cells without central caseation (unlike TB). Their presence is highly specific for Crohn''s when found in the appropriate clinical context. However, their absence does not exclude Crohn''s as they occur in only ~30-60% of cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Crohn Disease, p.798'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Crohn''s Disease','medium','flashcard','What are the extra-intestinal manifestations of Crohn''s disease?','["Peripheral arthropathy (most common), erythema nodosum, pyoderma gangrenosum, uveitis/episcleritis, primary sclerosing cholangitis (less common than in UC), ankylosing spondylitis, and growth retardation in children."]','A','Extra-intestinal manifestations occur in ~25-40% of IBD patients. Some (peripheral arthropathy, erythema nodosum) correlate with intestinal disease activity. Others (ankylosing spondylitis, PSC, uveitis) run an independent course. PSC is more strongly associated with UC than Crohn''s.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Inflammatory Bowel Disease, p.796'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Crohn''s Disease','hard','flashcard','What are the fistulating complications of Crohn''s disease and what are the presenting symptoms?','["Entero-enteric (bowel-to-bowel — often asymptomatic or diarrhoea), entero-vesical (bowel-to-bladder — pneumaturia, faecaluria), entero-cutaneous (bowel-to-skin — faeculent discharge), entero-vaginal (bowel-to-vagina — faeculent vaginal discharge), and perianal fistulae."]','A','Fistulae result from transmural Crohn''s inflammation penetrating through the bowel wall into adjacent structures. Perianal fistulae and abscesses are particularly debilitating and may be the presenting feature. Biologic therapy (anti-TNF agents: infliximab, adalimumab) promotes fistula closure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Crohn Disease, p.798'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Crohn''s Disease','easy','flashcard','What is the string sign on barium follow-through in Crohn''s disease?','["A thin linear stream of barium through a severely narrowed segment of terminal ileum, caused by acute oedema/spasm or chronic fibrotic stricture from transmural inflammation."]','A','The string sign is a radiological hallmark of terminal ileal Crohn''s disease on barium follow-through. It indicates significant luminal narrowing and may be associated with pre-stenotic dilatation. Chronic strictures causing obstruction may require surgical resection or strictureplasty.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Crohn Disease, p.798'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Crohn''s Disease','medium','flashcard','What genetic factor is most strongly associated with Crohn''s disease and what is its function?','["NOD2/CARD15 mutations (chromosome 16q12); NOD2 is an intracellular pattern recognition receptor for bacterial muramyl dipeptide in Paneth cells; loss of function impairs innate bacterial defence and triggers excessive NF-κB-mediated inflammation."]','A','NOD2 mutations are present in ~15-30% of Crohn''s disease patients (vs ~7% controls). Homozygous mutations carry a 20-40-fold increased risk of Crohn''s disease. NOD2 normally promotes bacterial killing and tolerance; its dysfunction allows dysbiosis to trigger an aberrant adaptive immune response.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Crohn Disease, p.798'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Crohn''s Disease','hard','flashcard','Why does Crohn''s disease affecting the terminal ileum cause specific nutritional deficiencies?','["The terminal ileum is the sole site of vitamin B12 (cobalamin) absorption (via intrinsic factor-B12 complex/cubilin receptors) and bile salt reabsorption (enterohepatic circulation). Ileal Crohn''s or resection → B12 deficiency (megaloblastic anaemia) and bile salt malabsorption (steatorrhoea, fat-soluble vitamin deficiency, cholesterol gallstones)."]','A','Bile salt malabsorption in terminal ileal disease reduces the bile salt pool, impairing fat emulsification and producing steatorrhoea. Unabsorbed bile salts reaching the colon also cause secretory diarrhoea. These specific consequences distinguish terminal ileal Crohn''s from colonic Crohn''s.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Crohn Disease, p.798'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Crohn''s Disease','easy','flashcard','What is cobblestoning in Crohn''s disease and what causes it?','["Cobblestoning: a pattern of oedematous islands of relatively preserved mucosa surrounded by a network of intersecting linear (longitudinal and transverse) ulcers, producing a paving-stone appearance on endoscopy and barium studies."]','A','Cobblestoning is caused by deep rose-thorn (fissuring) longitudinal ulcers intersected by transverse ulcers, leaving elevated oedematous mucosal islands. This is distinct from the pseudopolyps of UC (which are regenerating mucosal islands without intersecting ulcers).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Crohn Disease, p.798'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Crohn''s Disease','medium','flashcard','What is creeping fat (fat wrapping) in Crohn''s disease?','["Mesenteric adipose tissue encroaching over the serosal surface of the bowel, typically seen in surgically resected specimens; indicates transmural serosal inflammation; not seen in ulcerative colitis."]','A','Creeping fat is a characteristic macroscopic finding in Crohn''s disease specimens. It reflects transmural inflammation extending to the serosal surface and triggering mesenteric adipose tissue hypertrophy and migration around the bowel. The mesenteric fat also harbours lymph nodes which may show granulomata.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Crohn Disease, p.798'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Crohn''s Disease','hard','flashcard','What are the differences in cancer risk between Crohn''s disease and ulcerative colitis?','["Crohn''s: increased risk of small bowel adenocarcinoma (particularly in chronically inflamed segments, jejunum/ileum); also increased CRC risk in colonic Crohn''s (~4x normal after 20 years). UC: greater CRC risk than Crohn''s colitis; risk increases with disease extent and duration (>10 years pancolitis)."]','A','In Crohn''s disease, small bowel adenocarcinoma risk is ~20-40x that of the general population, making it the most serious malignant complication despite being rare in absolute terms. CRC risk in Crohn''s colitis is significant but lower than in UC of equivalent extent and duration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Crohn Disease, p.798'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Ulcerative Colitis','easy','flashcard','How does the distribution of bowel involvement in UC differ from Crohn''s disease?','["UC: rectum invariably involved, continuous proximal extension — proctitis, left-sided colitis, or pancolitis; mucosal and submucosal only. Crohn''s: discontinuous skip lesions, transmural, any GI tract from mouth to anus."]','A','The continuous distal-to-proximal pattern of UC is a key diagnostic feature. Disease activity is classified by extent: E1 (proctitis), E2 (left-sided, to splenic flexure), E3 (pancolitis). CRC risk correlates with extent and duration. Rectal sparing virtually rules out UC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Ulcerative Colitis, p.800'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Ulcerative Colitis','medium','flashcard','What is toxic megacolon and what are its causes and management principles?','["Toxic megacolon: acute non-obstructive colonic dilatation (transverse colon >6 cm) with systemic toxicity (fever, tachycardia, leukocytosis, hypotension); caused by severe UC, Crohn''s colitis, or infectious colitis (C. difficile). Management: IV fluids, steroids, antibiotics; colectomy if no improvement in 24-48 hours."]','A','Toxic megacolon results from transmural extension of inflammation (beyond mucosa) paralyzing the muscularis propria, preventing effective peristalsis. Risk factors include hypokalaemia, anticholinergics, opiates, and colonoscopy during active disease. Perforation carries ~40% mortality.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Ulcerative Colitis, p.800'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Ulcerative Colitis','easy','flashcard','What is the histological hallmark of active UC, and what architectural changes indicate chronicity?','["Active UC: crypt abscesses (neutrophils within crypt lumina). Chronic UC: crypt architectural distortion (branching, shortening, irregular spacing), goblet cell depletion, Paneth cell metaplasia (distal to hepatic flexure), and basal plasmacytosis."]','A','Basal plasmacytosis (plasma cells below the crypt bases) is an early and sensitive histological marker of UC, predating architectural distortion. Crypt abscesses indicate active injury. The combination of active and chronic changes throughout the colon (in a continuous pattern) is highly characteristic of UC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Ulcerative Colitis, p.800'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Ulcerative Colitis','hard','flashcard','What is the mechanism and significance of dysplasia in UC, and when does surgery become necessary?','["Dysplasia (low-grade or high-grade intraepithelial neoplasia) arises from chronically inflamed colonic mucosa and is the morphological precursor to colitis-associated colorectal cancer. High-grade dysplasia or flat low-grade dysplasia in the context of UC warrants colectomy due to high risk of synchronous/metachronous cancer."]','A','Colitis-associated CRC differs from sporadic CRC in that TP53 mutations occur earlier (before APC), and microsatellite instability is common. Risk increases with disease duration (>10 years pancolitis), extent (pancolitis > left-sided), severity, and co-existing PSC. 5-ASA reduces cancer risk in UC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Colitis-Associated Neoplasia, p.801'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Ulcerative Colitis','medium','flashcard','What is primary sclerosing cholangitis (PSC) and how does it relate to UC?','["PSC: progressive periductal (onion-skin) fibrosis causing multifocal stricturing of intra- and extrahepatic bile ducts; occurs in ~5% of UC patients; ~75% of PSC patients have UC. Presents with cholestatic jaundice, pruritus, fatigue; MRCP shows beaded appearance; risk of cholangiocarcinoma."]','A','PSC is the most common hepatobiliary extra-intestinal manifestation of UC. Unlike most UC extra-intestinal manifestations, PSC does not improve with colectomy. It may be diagnosed before, concurrent with, or after UC diagnosis. Liver transplantation is the only effective treatment for end-stage PSC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Ulcerative Colitis, p.800'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Ulcerative Colitis','easy','flashcard','What are pseudopolyps in UC and how do they form?','["Non-neoplastic projections of residual or regenerating oedematous mucosa surrounded by areas of ulceration; represent healing mucosa between ulcers; carry no direct malignant potential."]','A','Pseudopolyps form in active and healing UC when surrounding mucosa is ulcerated and denuded, leaving islands of relatively intact or regenerating mucosa elevated above the level of the surrounding ulcerated surface. They are easily seen on colonoscopy and may be confused with true adenomatous polyps.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Ulcerative Colitis, p.800'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Ulcerative Colitis','medium','flashcard','What is the ''lead-pipe'' colon in UC and what causes it?','["Lead-pipe colon: loss of haustral folds, foreshortening, and rigidity on barium enema producing a featureless tube-like appearance; caused by chronic mucosal damage, submucosal fibrosis, and muscularis mucosae hypertrophy."]','A','The lead-pipe colon is a late radiological finding in chronic UC, reflecting longstanding mucosal damage and fibrotic remodelling. It is associated with poor compliance and increased risk of CRC. The differential includes Hirschsprung disease and chronic laxative abuse.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Ulcerative Colitis, p.800'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Ulcerative Colitis','hard','flashcard','Describe the key histological features distinguishing UC from Crohn''s colitis.','["UC: mucosal/submucosal inflammation only, diffuse crypt distortion throughout colon, no granulomas, rectal involvement invariable. Crohn''s colitis: transmural inflammation, non-caseating granulomas (30-60%), skip lesions, rectal sparing common, perianal disease."]','A','In approximately 5-15% of IBD cases, definitive distinction between UC and Crohn''s colitis is not possible even after colectomy — termed ''indeterminate colitis.'' This has clinical implications particularly for surgical planning (pouch surgery for UC vs Crohn''s colitis carry different outcomes).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Ulcerative Colitis/Crohn Disease, p.798-800'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Ulcerative Colitis','easy','flashcard','What is backwash ileitis in the context of UC pancolitis?','["Superficial non-granulomatous ileal inflammation occurring in ~20% of patients with UC pancolitis, caused by reflux of colonic contents through an incompetent ileocaecal valve; should not be mistaken for Crohn''s ileitis (skip lesion)."]','A','The distinction is crucial: backwash ileitis affects only a short segment of terminal ileum (usually <10 cm), is superficial and non-granulomatous, and resolves with colectomy. Crohn''s ileitis causes transmural inflammation with granulomas, strictures, and cobblestoning.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Ulcerative Colitis, p.800'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Inflammatory Bowel Disease - Ulcerative Colitis','medium','flashcard','After how many years of extensive UC does CRC risk become clinically significant, and what is the screening strategy?','["CRC risk becomes significant after 10 years of extensive (pancolonic) UC; surveillance colonoscopy with chromoendoscopy or systematic biopsies every 1-2 years after 10 years; high-grade dysplasia warrants colectomy; 5-ASA therapy reduces cancer risk."]','A','The risk of CRC in UC correlates with disease extent (pancolitis > left-sided colitis > proctitis), duration, severity, co-existing PSC, and family history of CRC. Annual surveillance after 10 years of pancolitis or 15 years of left-sided colitis is recommended in most guidelines.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Colitis-Associated Neoplasia, p.801'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Colorectal Carcinoma','easy','flashcard','Describe the Vogelstein adenoma-carcinoma sequence in colorectal cancer.','["APC loss (early — initiates adenoma) → KRAS activating mutation (adenoma growth) → SMAD4/DPC4 loss → TP53 mutation (malignant transformation) → invasive adenocarcinoma. This chromosomal instability pathway accounts for ~85% of sporadic CRC."]','A','Each step in the Vogelstein sequence has a corresponding histological correlate: APC loss creates early adenomas; KRAS mutation drives adenoma growth; TP53 loss enables invasion. The process takes 10-15 years on average, providing a window for colonoscopic prevention by polypectomy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Adenocarcinoma, p.810'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Colorectal Carcinoma','medium','flashcard','What is familial adenomatous polyposis (FAP) and how is it managed?','["FAP: autosomal dominant germline APC mutation causing hundreds to thousands of colorectal adenomatous polyps from puberty; 100% lifetime CRC risk without intervention; managed with prophylactic colectomy (typically in late teens/early 20s) and endoscopic surveillance for duodenal/gastric polyps."]','A','FAP accounts for ~1% of CRC. Gardner syndrome (FAP variant) includes extracolonic features: desmoid tumours, osteomas, epidermoid cysts, supernumerary teeth, and thyroid cancer. Attenuated FAP (AFAP) has fewer polyps (<100) and delayed onset. Chemoprevention with sulindac/celecoxib may reduce polyp burden.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Adenomatous Polyposis, p.809'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Colorectal Carcinoma','medium','flashcard','What is Lynch syndrome (HNPCC) and what cancers does it predispose to?','["Lynch syndrome: autosomal dominant germline mutations in DNA mismatch repair genes (MLH1, MSH2, MSH6, PMS2) → microsatellite instability (MSI-H) → CRC (typically right-sided, mucinous, poorly differentiated), endometrial, ovarian, gastric, and urological tract cancers."]','A','Lynch syndrome accounts for ~3-5% of CRC. Amsterdam II criteria and Bethesda guidelines identify at-risk patients. Tumour testing for MSI and immunohistochemistry for MMR proteins is performed on all CRC under 70. Germline testing confirms diagnosis. Annual colonoscopy from age 20-25 is recommended.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Hereditary Non-Polyposis Colorectal Cancer, p.810'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Colorectal Carcinoma','hard','flashcard','Describe the Dukes staging system for colorectal carcinoma and approximate 5-year survival for each stage.','["Dukes A: mucosa/submucosa (~90% 5-yr survival). Dukes B: through muscularis propria, no nodes (~65%). Dukes C: regional lymph node metastases (~30%). Dukes D (Astler-Coller modification): distant metastases (~5%)."]','A','Although largely superseded by the TNM staging system, Dukes staging remains commonly tested. TNM correlations: Dukes A = T1-2N0M0; Dukes B = T3-4N0M0; Dukes C = any T, N1-2, M0; Dukes D = any T, any N, M1. Adjuvant chemotherapy (FOLFOX) is given for stage III (Dukes C) disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Adenocarcinoma, p.810'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Colorectal Carcinoma','easy','flashcard','How do the clinical presentations of right-sided and left-sided colorectal carcinoma differ?','["Right-sided (proximal): iron deficiency anaemia from occult bleeding, palpable mass, often no obstructive symptoms (large calibre lumen). Left-sided (distal): altered bowel habit, obstructive symptoms (colicky pain, constipation), rectal bleeding, pencil-thin stools, apple-core appearance on barium enema."]','A','The diameter of the right colon is larger (~6.5 cm vs ~2.5 cm for sigmoid), allowing tumours to grow silently for longer before causing obstruction. Right-sided cancers are often polypoid/exophytic; left-sided are typically annular/constricting. Left-sided cancers more commonly present as surgical emergencies (obstruction, perforation).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Adenocarcinoma, p.810'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Colorectal Carcinoma','medium','flashcard','What features of a colorectal adenoma increase the risk of malignant transformation?','["High-risk features: villous architecture (vs tubular), size >1 cm, high-grade dysplasia, sessile (vs pedunculated) morphology, multiple adenomas. Villous adenomas >4 cm have ~40% malignant potential."]','A','The degree of villous architecture most strongly predicts malignant potential: tubular adenomas ~5%, tubulovillous adenomas ~20%, villous adenomas ~40%. Size >1 cm is the most practical risk stratifier for surveillance intervals. High-grade dysplasia (=carcinoma in situ) in an adenoma requires complete resection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Neoplastic Polyps, p.807'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Colorectal Carcinoma','hard','flashcard','What is the serrated pathway of colorectal carcinogenesis?','["Serrated pathway: BRAF V600E mutation (in sessile serrated adenoma/polyp, SSA/P) → MLH1 promoter methylation → MSI-H → right-sided mucinous CRC; accounts for ~15-20% of sporadic CRC. Distinct from the conventional APC-KRAS-TP53 chromosomal instability pathway."]','A','Sessile serrated adenomas/polyps (SSA/P) are endoscopically flat, pale, right-sided lesions often masked by adherent mucus, making them easy to miss at colonoscopy. They account for a significant proportion of post-colonoscopy (interval) CRCs. Their BRAF mutation differentiates them from hyperplastic polyps (also BRAF mutated but no MLH1 methylation, no malignant potential).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Adenocarcinoma, p.810'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Colorectal Carcinoma','easy','flashcard','What is the most common site of distant metastasis in colorectal carcinoma and why?','["Liver — via the portal venous system. The portal vein drains blood from the colon directly to the liver, making it the first capillary bed encountered by circulating tumour cells."]','A','Hepatic metastases from CRC are present at diagnosis in ~20-25% of patients. Isolated resectable hepatic metastases (Fong criteria) can be cured by hepatectomy with ~30-40% 5-year survival. Pulmonary metastases are the second most common site. Rectal cancer may also metastasise via the systemic venous route (inferior rectal veins → IVC) directly to the lungs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Adenocarcinoma, p.810'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Colorectal Carcinoma','medium','flashcard','What is microsatellite instability (MSI) in colorectal cancer and what are its clinical implications?','["MSI: accumulation of mutations in short tandem repeat sequences (microsatellites) due to defective DNA mismatch repair; MSI-H CRC has better prognosis stage-for-stage than MSS CRC, better response to immunotherapy (pembrolizumab), and is the molecular hallmark of Lynch syndrome."]','A','MSI testing (PCR for microsatellite loci) and MMR immunohistochemistry (MLH1, MSH2, MSH6, PMS2 protein expression) are performed on all CRC specimens. Sporadic MSI-H CRC (from MLH1 hypermethylation + BRAF V600E) has a better prognosis but does not respond to standard adjuvant 5-FU chemotherapy. Lynch syndrome MSI-H lacks BRAF mutation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Adenocarcinoma, p.810'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Colorectal Carcinoma','hard','flashcard','What is the molecular difference between sporadic and hereditary MSI-H colorectal cancer?','["Sporadic MSI-H CRC: MLH1 promoter hypermethylation (epigenetic silencing) + BRAF V600E mutation — acquired somatic event. Hereditary MSI-H CRC (Lynch syndrome): germline mutation in MLH1, MSH2, MSH6, or PMS2 — no BRAF V600E mutation."]','A','BRAF V600E mutation testing distinguishes sporadic from hereditary MSI-H CRC: sporadic cases have BRAF V600E; Lynch syndrome does not. This is clinically important: BRAF V600E excludes Lynch syndrome, avoiding unnecessary germline genetic testing in patients with sporadic MSI-H tumours.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Hereditary Non-Polyposis Colorectal Cancer, p.810'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Hepatitis','easy','flashcard','What are the serological markers of acute hepatitis B infection?','["HBsAg: first marker to appear (indicates infection). IgM anti-HBc: marker of acute infection. HBeAg: indicates high replication and infectivity. Anti-HBs appears after recovery (immunity). The ''window period'' is when HBsAg has cleared but anti-HBs not yet detectable — IgM anti-HBc confirms recent infection."]','A','The serological window period in HBV is when neither HBsAg nor anti-HBs is detectable. IgM anti-HBc is the only positive marker at this time, confirming recent acute HBV infection. HBV DNA PCR is positive throughout infection and is the most sensitive marker of active replication.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Viral Hepatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Hepatitis','medium','flashcard','What histological finding is characteristic of chronic hepatitis B on liver biopsy?','["Ground-glass hepatocytes: smooth, finely granular cytoplasm due to abundant smooth endoplasmic reticulum packed with HBsAg. Confirmed by orcein or Victoria blue stain (which stains HBsAg-containing ER brown/blue)."]','A','Ground-glass hepatocytes are a distinctive feature of chronic HBV infection, reflecting massive intracellular accumulation of HBsAg within proliferating smooth ER. They are not specific (also seen in glycogen storage in type 1 diabetes, cyanamide therapy) but strongly suggest HBV in the right context.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Viral Hepatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Hepatitis','easy','flashcard','Which hepatitis virus has the highest rate of chronicity and how does this compare to other hepatitis viruses?','["HCV has the highest chronicity rate: 75-85% of infected individuals develop chronic infection. HBV: ~5-10% of adults (but ~90% of neonates). HDV superinfection in HBV carriers: ~80% chronicity. HAV and HEV: no chronic infection."]','A','The high chronicity rate of HCV is due to the virus''s ability to evade innate immune responses through NS3/4A protease cleavage of MAVS and TRIF signalling adaptors, preventing interferon production. This immune evasion strategy enables persistent infection in most adults.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Viral Hepatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Hepatitis','medium','flashcard','What is hepatitis D virus and why does it require co-infection with HBV?','["Hepatitis D virus (HDV, delta agent) is a defective negative-sense single-stranded RNA virus that requires HBsAg from HBV to form its own envelope. It cannot infect hepatocytes without simultaneous HBV infection. HDV superinfection of HBV carriers accelerates cirrhosis."]','A','HDV has two patterns: co-infection (simultaneous HBV+HDV acute infection — usually self-limiting, ~5% chronicity) and superinfection (HDV infecting an HBV chronic carrier — ~80% chronicity, accelerated liver disease). Antiviral therapy options for HDV are limited; bulevirtide has recent approval.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Viral Hepatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Hepatitis','hard','flashcard','What are the serological patterns of hepatitis B in different clinical scenarios?','["Vaccination: anti-HBs positive only. Resolved natural infection: anti-HBs + IgG anti-HBc. Chronic HBV: HBsAg + IgG anti-HBc (±HBeAg). Acute HBV: HBsAg + IgM anti-HBc (±HBeAg). Window period: IgM anti-HBc only."]','A','Understanding HBV serology is critical. Isolated anti-HBc (no HBsAg, no anti-HBs) may represent: window period acute infection, resolved infection with waning anti-HBs, or occult HBV. HBV DNA PCR resolves ambiguity. Anti-HBe (with negative HBeAg) in a chronic carrier indicates seroconversion to a less replicative phase (may still have active disease if HBeAg-negative variant).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Viral Hepatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Hepatitis','medium','flashcard','What is the significance of bridging necrosis in viral hepatitis on liver biopsy?','["Bridging necrosis (confluent hepatocyte necrosis spanning portal tracts to terminal hepatic venules or portal-to-portal) indicates severe acute hepatitis and is a precursor to post-necrotic scarring and cirrhosis. It denotes a worse prognosis than focal lobular necrosis."]','A','Bridging necrosis occurs in severe acute viral hepatitis (most commonly HBV) and indicates extensive hepatocyte loss. The resulting collapse of the reticulin framework leads to approximation of portal tracts and hepatic venules, predisposing to fibrous bridging and ultimately post-necrotic cirrhosis if the underlying cause persists.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Viral Hepatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Hepatitis','easy','flashcard','Which hepatitis virus causes fulminant hepatitis with particularly high mortality in pregnant women?','["Hepatitis E virus (HEV genotypes 1 and 2), with 15-25% mortality in pregnant women (especially third trimester); transmitted faeco-orally, endemic in developing countries; no chronic infection in immunocompetent hosts."]','A','HEV is transmitted through contaminated water (genotypes 1, 2) or zoonotic contact with pigs (genotypes 3, 4 in developed countries). In immunocompromised patients, HEV genotype 3 can cause chronic hepatitis. An HEV vaccine (HEV239) is licensed in China but not yet globally.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Viral Hepatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Hepatitis','medium','flashcard','What are the modes of transmission of hepatitis A, B, C, and E?','["HAV: faeco-oral. HBV: parenteral, sexual, perinatal (vertical). HCV: predominantly parenteral (IV drug use, blood transfusion pre-1992, needlestick). HEV: faeco-oral (genotypes 1,2); zoonotic/pork (genotypes 3,4 in developed countries)."]','A','HCV transmission via sexual contact is relatively inefficient (~0.1%/year in monogamous HIV-negative couples). Vertical HCV transmission occurs in ~5%. HBV is 100x more infectious than HIV per needlestick. Screening blood donations for HBsAg (1971) and anti-HCV (1992) dramatically reduced transfusion-associated hepatitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Viral Hepatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Hepatitis','hard','flashcard','How does HCV evade the immune system to establish chronic infection?','["HCV NS3/4A protease cleaves MAVS (mitochondrial antiviral signalling protein) and TRIF, blocking type I interferon production. HCV also mutates rapidly (quasi-species diversity), escaping T-cell and antibody responses. High viral replication rate (~10^12 virions/day) facilitates immune escape."]','A','The loss of innate immune signalling through MAVS and TRIF cleavage prevents the early interferon response that would otherwise clear HCV. The virus additionally induces T-cell exhaustion through PD-1/PD-L1 upregulation. Direct-acting antivirals (DAAs) achieve SVR >95% by targeting NS3/4A protease, NS5A, and NS5B polymerase.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Viral Hepatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Hepatitis','easy','flashcard','What serological marker indicates past hepatitis A infection or immunity from vaccination?','["IgG anti-HAV antibody — indicates past infection (natural immunity) or vaccination. IgM anti-HAV indicates acute infection. HAV produces lifelong immunity after natural infection or vaccination."]','A','IgG anti-HAV persists for life after natural HAV infection, providing lifelong immunity. The HAV vaccine is a formalin-inactivated vaccine that induces protective anti-HAV levels in >95% of recipients after 2 doses. HAV does not establish chronic infection and causes no carrier state.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Viral Hepatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Cirrhosis and Complications','easy','flashcard','Define cirrhosis and list its most common causes.','["Cirrhosis: irreversible diffuse hepatic fibrosis with replacement of normal architecture by regenerative nodules, causing portal hypertension and hepatic synthetic failure. Common causes: alcohol (most common in West), chronic HBV/HCV, NAFLD/NASH, autoimmune hepatitis, PBC, PSC, Wilson''s disease, haemochromatosis."]','A','Cirrhosis represents the end stage of chronic liver injury, regardless of aetiology. The fibrosis is characterised by bridging fibrous septa linking portal tracts and hepatic venules. Regenerative nodules form as hepatocytes attempt to compensate. Once established, cirrhosis is irreversible, though progression can be halted by treating the underlying cause.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Cirrhosis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Cirrhosis and Complications','medium','flashcard','What is spontaneous bacterial peritonitis (SBP) and how is it diagnosed?','["SBP: bacterial infection of ascitic fluid without an identifiable intra-abdominal source; diagnosed by PMN count >250 cells/mm³ in ascitic fluid; most commonly caused by E. coli and Klebsiella; treated with empirical third-generation cephalosporin (ceftriaxone)."]','A','SBP arises from bacterial translocation across the gut wall into the ascitic fluid, facilitated by portal hypertension, intestinal dysmotility, and bacterial overgrowth. Norfloxacin prophylaxis is used in high-risk cirrhotic patients (prior SBP, ascitic protein <10 g/L). Albumin infusion alongside antibiotics reduces mortality.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Cirrhosis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Cirrhosis and Complications','medium','flashcard','What is hepatorenal syndrome (HRS) and how is it classified?','["HRS: functional renal failure in cirrhosis without intrinsic renal pathology. Type 1 (HRS-AKI): rapidly progressive (creatinine doubles to >2.5 mg/dL in <2 weeks); poor prognosis. Type 2 (HRS-CKD): slower progressive, associated with refractory ascites."]','A','HRS results from severe splanchnic vasodilation (from portal hypertension) activating RAAS and SNS, causing renal vasoconstriction. Kidneys function normally if transplanted. Treatment: terlipressin + albumin reduces portal pressure and improves renal perfusion. TIPSS or liver transplantation are definitive treatments.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Cirrhosis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Cirrhosis and Complications','hard','flashcard','What are the Milan criteria for liver transplantation in HCC and why do they matter?','["Milan criteria: single HCC nodule ≤5 cm, or up to 3 nodules each ≤3 cm, with no macrovascular invasion and no extrahepatic spread. Patients within Milan criteria have post-transplant 5-year survival comparable to transplantation for benign disease (~70%)."]','A','The Milan criteria were established in 1996 by Mazzaferro et al. and remain the gold-standard benchmark for HCC transplantation selection in most transplant centres. Expanded criteria (e.g., UCSF criteria, ''up-to-7'' criteria) allow slightly larger tumours with similar outcomes in selected patients. Bridge therapy (TACE, ablation) may downstage patients to within Milan criteria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Hepatocellular Carcinoma, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Cirrhosis and Complications','easy','flashcard','What are the five components of the Child-Pugh score?','["1. Serum bilirubin (μmol/L), 2. Serum albumin (g/L), 3. Prothrombin time/INR, 4. Ascites (none/mild/moderate-severe), 5. Hepatic encephalopathy (grade). Scored 1-3 per component; total 5-15. Child A (5-6): good function; Child B (7-9): moderate; Child C (10-15): poor function."]','A','The Child-Pugh score was originally designed to predict surgical mortality in cirrhosis. Child A = ~10% surgical mortality; Child C = ~80%. It has been partially superseded by MELD score (which uses creatinine, INR, bilirubin, and sodium) for organ allocation in liver transplantation, as MELD more accurately predicts 90-day mortality.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Cirrhosis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Cirrhosis and Complications','medium','flashcard','What is hepatic encephalopathy and how is it graded?','["Hepatic encephalopathy: neuropsychiatric syndrome in cirrhosis from elevated ammonia (and other toxins) crossing the blood-brain barrier causing astrocyte swelling. Grade I: subtle confusion, altered sleep. Grade II: drowsiness, inappropriate behaviour. Grade III: marked confusion, incoherence. Grade IV: coma."]','A','Triggers of hepatic encephalopathy include: GI bleeding (protein load), infection, constipation, electrolyte disturbance (hypokalaemia), sedatives, and excessive dietary protein. Treatment: lactulose (reduces NH3 production/absorption), rifaximin (reduces gut bacterial ammonia production), treat precipitants.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Cirrhosis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Cirrhosis and Complications','hard','flashcard','What are the portosystemic collateral pathways that open in portal hypertension?','["1. Oesophageal varices (left gastric → oesophageal veins). 2. Haemorrhoids (superior → middle/inferior rectal veins). 3. Caput medusae (paraumbilical veins → epigastric veins). 4. Retroperitoneal collaterals (splenorenal, gastrorenal). All represent reversal of portal-to-systemic venous flow."]','A','Each portosystemic collateral has clinical significance: oesophageal varices — life-threatening haemorrhage; haemorrhoids — bleeding; caput medusae — rarely causes significant bleeding. Splenorenal shunts can be created surgically (TIPSS) to decompress portal hypertension and prevent variceal re-bleeding.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Cirrhosis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Cirrhosis and Complications','easy','flashcard','What is the most common primary liver cancer and what are its main risk factors?','["Hepatocellular carcinoma (HCC): most common primary liver cancer globally; main risk factors — chronic HBV (can occur without cirrhosis), chronic HCV (typically with cirrhosis), alcoholic cirrhosis, NAFLD/NASH cirrhosis, and aflatoxin B1 exposure (with HBV in Sub-Saharan Africa/Asia)."]','A','HCC accounts for ~80% of primary liver cancers. AFP is elevated in ~70% and used alongside ultrasound for 6-monthly surveillance in cirrhotic patients. LI-RADS imaging criteria (arterial enhancement + washout) diagnose HCC on CT/MRI without biopsy. Sorafenib is standard first-line systemic therapy for advanced HCC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Hepatocellular Carcinoma, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Cirrhosis and Complications','medium','flashcard','What are Mallory-Denk bodies and in which conditions are they found?','["Mallory-Denk bodies: eosinophilic, irregular intracytoplasmic inclusions of ubiquitinated keratin intermediate filaments (keratins 8 and 18) in hepatocytes. Found in: alcoholic hepatitis (most classic), NASH, primary biliary cholangitis, Wilson''s disease, and hepatocellular carcinoma."]','A','Mallory-Denk bodies form when ubiquitin-proteasome pathway is overwhelmed, allowing misfolded keratins to accumulate. They indicate hepatocyte stress and injury. In alcoholic hepatitis, their presence (along with ballooning degeneration, lobular neutrophilic inflammation, and steatosis) defines the histological picture.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Alcoholic Liver Disease, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Liver Disease - Cirrhosis and Complications','hard','flashcard','Describe the pathophysiology of ascites formation in cirrhosis.','["Portal hypertension → splanchnic vasodilation (NO-mediated) → reduced effective circulating volume → RAAS activation → sodium/water retention → increased lymph production exceeding thoracic duct capacity → ascites. Hypoalbuminaemia (reduced oncotic pressure) exacerbates fluid extravasation."]','A','Ascites management: sodium restriction (<2 g/day), diuretics (spironolactone ± furosemide), paracentesis (large volume — with albumin 8 g per litre removed), TIPSS for refractory ascites. Spontaneous bacterial peritonitis prophylaxis with norfloxacin or ciprofloxacin for high-risk patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Cirrhosis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Biliary Disease','easy','flashcard','What are the three types of gallstones and their associations?','["Cholesterol stones (~80%): pale, multiple, associated with obesity/female/OCP/rapid weight loss. Black pigment stones: associated with chronic haemolysis (sickle cell, spherocytosis), sterile bile. Brown pigment stones: associated with biliary infection/stasis, calcium bilirubinate from bacterial deconjugation."]','A','The 4Fs for cholesterol gallstones: Fat, Female, Forty, Fertile. Obesity increases cholesterol secretion; OCP and pregnancy increase cholesterol saturation and reduce gallbladder motility. Rapid weight loss (e.g., bariatric surgery) increases bile cholesterol saturation. Ursodeoxycholic acid can dissolve small cholesterol stones.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Cholelithiasis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Biliary Disease','medium','flashcard','Describe the classic clinical presentation of acute cholecystitis.','["Acute cholecystitis: severe, constant right upper quadrant pain radiating to right shoulder/back (biliary colic precedes), fever, nausea, vomiting, Murphy''s sign (inspiratory arrest on RUQ palpation), leukocytosis, and elevated CRP."]','A','Acute cholecystitis is caused by gallstone impaction in the cystic duct (90%) or acalculous cholecystitis in critically ill patients (10%). USS shows gallbladder wall thickening >3 mm, pericholecystic fluid, and gallstones. HIDA scan (99mTc-HIDA) confirms acute cholecystitis when gallbladder is not visualised. Treatment: laparoscopic cholecystectomy (early).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Cholecystitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Biliary Disease','medium','flashcard','What is primary sclerosing cholangitis (PSC) and what are its complications?','["PSC: progressive periductal fibrosis causing stricturing and dilatation of intra- and extrahepatic bile ducts; MRCP shows beaded appearance; associated with UC (~75% of PSC patients); complications include biliary strictures, recurrent cholangitis, secondary biliary cirrhosis, and cholangiocarcinoma (~10-15% lifetime risk)."]','A','PSC is diagnosed by MRCP/ERCP (beaded bile ducts). ERCP allows treatment of dominant strictures by dilation/stenting. No medical therapy (including UDCA) has been proven to slow disease progression. Liver transplantation is the only effective treatment for advanced PSC, but PSC can recur in the graft.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Primary Sclerosing Cholangitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Biliary Disease','hard','flashcard','Distinguish primary biliary cholangitis (PBC) from primary sclerosing cholangitis (PSC) histologically and clinically.','["PBC: granulomatous destruction of small intrahepatic ducts (florid duct lesion), AMA positive, middle-aged women, pruritus/fatigue, cholestatic LFTs. PSC: periductal onion-skin fibrosis of large intra- and extrahepatic ducts, pANCA positive, associated with UC, MRCP beaded appearance, risk of cholangiocarcinoma."]','A','Key distinguishing features: PBC targets small interlobular bile ducts; PSC targets large ducts visible on cholangiography. AMA is present in >95% of PBC, absent in PSC. UC association is with PSC (not PBC). UDCA improves liver enzymes and slows progression in PBC; no proven medical therapy for PSC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Primary Biliary Cholangitis/PSC, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Biliary Disease','easy','flashcard','What is Courvoisier''s law and what does a palpable gallbladder with painless jaundice suggest?','["Courvoisier''s law: a palpable non-tender gallbladder with painless obstructive jaundice suggests malignant CBD obstruction (not gallstones), because chronic cholelithiasis produces a fibrotic, non-distensible gallbladder. Most commonly caused by pancreatic head carcinoma or periampullary tumour."]','A','In gallstone disease (choledocholithiasis), the gallbladder is chronically thickened and fibrotic from repeated inflammation, so it cannot distend when the CBD is obstructed. In malignant obstruction (gradual), the normal gallbladder distends, producing Courvoisier''s sign. Exceptions exist (Mirizzi syndrome, Klatskin tumour).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Biliary/Pancreatic Carcinoma, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Biliary Disease','medium','flashcard','What are the risk factors for cholangiocarcinoma and how is it classified anatomically?','["Risk factors: PSC (Western countries), Opisthorchis viverrini/Clonorchis sinensis liver flukes (Southeast Asia), choledochal cysts, hepatolithiasis, Caroli disease. Anatomical classification: intrahepatic (peripheral), perihilar (Klatskin tumour — most common, ~60%), and distal extrahepatic."]','A','Klatskin tumours arise at the biliary confluence and are the most common cholangiocarcinoma type. They often present with painless obstructive jaundice and cannot be distinguished from PSC-associated strictures without biopsy or brush cytology. CA 19-9 + CEA elevation supports malignancy. Most are unresectable at diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Cholangiocarcinoma, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Biliary Disease','hard','flashcard','What is the pathogenesis of cholesterol gallstone formation?','["Three conditions required (Admirand-Small triangle): (1) supersaturation of bile with cholesterol (lithogenic index >1), (2) nucleation of cholesterol crystals (promoted by mucin, calcium, proteins), and (3) gallbladder hypomotility (bile stasis allowing crystal growth). Ezetimibe and statins reduce biliary cholesterol secretion."]','A','Bile supersaturation with cholesterol is the prerequisite for cholesterol stone formation. Obesity increases HMG-CoA reductase activity (cholesterol synthesis); OCP increases cholesterol secretion and reduces gallbladder motility; rapid weight loss mobilises cholesterol from adipose tissue into bile. Bile salts and phospholipids normally keep cholesterol in solution via mixed micelles.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Cholelithiasis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Biliary Disease','easy','flashcard','What is acute acalculous cholecystitis and who is at risk?','["Acute cholecystitis without gallstones, occurring in critically ill patients (post-major surgery, trauma, burns, ICU, prolonged TPN, mechanical ventilation); caused by gallbladder wall ischaemia and bile stasis; higher morbidity and mortality (~30%) than calculous cholecystitis."]','A','Acalculous cholecystitis accounts for ~5-10% of acute cholecystitis cases. The pathogenesis involves ischaemia (reduced gallbladder perfusion in low flow states), bile stasis (from TPN/fasting), and secondary infection. Diagnosis is by USS or hepatobiliary scintigraphy (HIDA). Treatment: percutaneous cholecystostomy or cholecystectomy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Cholecystitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Biliary Disease','medium','flashcard','What is Mirizzi syndrome?','["External compression of the common hepatic duct by a gallstone impacted in the cystic duct or Hartmann''s pouch, causing obstructive jaundice. May mimic cholangiocarcinoma on imaging. Classified by degree of duct wall involvement (Csendes classification)."]','A','Mirizzi syndrome is a rare complication of cholelithiasis. The impacted stone compresses the CHD from outside, causing obstructive jaundice and cholangitis. In advanced cases (Csendes type III-IV), the stone erodes through the cystic duct wall into the CHD (cholecystocholedochal fistula). Surgery is complex due to distorted anatomy.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Cholelithiasis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Biliary Disease','hard','flashcard','What autoantibody is characteristic of primary biliary cholangitis and what is its target?','["Antimitochondrial antibody (AMA), specifically anti-M2, targeting the E2 subunit of pyruvate dehydrogenase complex (PDC-E2) on the inner mitochondrial membrane; present in >95% of PBC patients with high specificity."]','A','AMA-M2 is pathognomonic for PBC when present in the right clinical context (cholestatic liver disease in middle-aged women). PDC-E2 is aberrantly expressed on the apical surface of biliary epithelial cells (cholangiocytes) in PBC, where it becomes an autoimmune target for CD4+ and CD8+ T-cell-mediated destruction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 18: Primary Biliary Cholangitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Pancreatic Disease','easy','flashcard','What are the two most common causes of acute pancreatitis and the mnemonic for other causes?','["Gallstones (45%) and alcohol (35%) account for ~80%. Mnemonic ''GET SMASHED'': Gallstones, Ethanol, Trauma, Steroids, Mumps/Malignancy, Autoimmune, Scorpion sting, Hyperlipidaemia/Hypercalcaemia/Hypothermia, ERCP, Drugs (azathioprine, thiazides, valproate)."]','A','Gallstones cause pancreatitis by transient or persistent ampullary obstruction, causing premature intrapancreatic activation of pancreatic enzymes (trypsinogen → trypsin). Alcohol causes pancreatitis through direct acinar toxicity, fatty acid ethyl ester formation, and oxidative stress.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17/18: Acute Pancreatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Pancreatic Disease','medium','flashcard','What is the Ranson criteria for acute pancreatitis severity assessment?','["At admission: age >55, WBC >16,000/μL, glucose >200 mg/dL, LDH >350 IU/L, AST >250 IU/L. At 48 hours: haematocrit fall >10%, BUN rise >5 mg/dL, Ca²⁺ <8 mg/dL, PaO2 <60 mmHg, base deficit >4 mEq/L, fluid sequestration >6L. Score ≥3 = severe (15% mortality); ≥7 = near 100% mortality."]','A','Ranson''s criteria predict severity at admission and at 48 hours. They are validated for gallstone pancreatitis (with modified values) and alcohol pancreatitis. Alternative severity scores include the BISAP score (5 criteria in 24 hours) and the Bedside Index of Severity in Acute Pancreatitis. CT severity index (Balthazar) assesses necrosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17/18: Acute Pancreatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Pancreatic Disease','medium','flashcard','What are Cullen''s sign and Grey Turner''s sign and what do they indicate?','["Cullen''s sign: periumbilical bruising (ecchymosis). Grey Turner''s sign: flank bruising (ecchymosis). Both indicate retroperitoneal haemorrhage tracking along fascial planes in severe necrotising/haemorrhagic pancreatitis. They typically appear 24-48 hours after onset and indicate a poor prognosis."]','A','These signs are rare (~1-3% of acute pancreatitis cases) and indicate haemorrhagic pancreatitis with retroperitoneal blood tracking along the falciform ligament (Cullen''s) or lateroconal fascia (Grey Turner''s). They are associated with high mortality and indicate necrotising pancreatitis requiring intensive care management.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17/18: Acute Pancreatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Pancreatic Disease','hard','flashcard','What are the features of pancreatic ductal adenocarcinoma and why does it carry such a poor prognosis?','["Features: head (60-70%) > body > tail; painless obstructive jaundice (head), CA 19-9 elevated, Courvoisier''s sign, weight loss, venous thrombosis (Trousseau''s sign). Poor prognosis (~5% 5-year survival) because: late presentation (no early symptoms), early vascular invasion and lymphatic spread, resectable in only ~20% at diagnosis."]','A','Pancreatic ductal adenocarcinoma arises predominantly from KRAS mutations (>90%) in pancreatic intraepithelial neoplasia (PanIN) precursor lesions. Subsequent CDKN2A, SMAD4, and TP53 mutations drive progression. Only the Whipple procedure (pancreaticoduodenectomy) offers potential cure, but most patients present with unresectable disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17/18: Pancreatic Carcinoma, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Pancreatic Disease','easy','flashcard','What is a pancreatic pseudocyst and how does it differ from a true pancreatic cyst?','["Pancreatic pseudocyst: walled-off collection of amylase-rich fluid lacking an epithelial lining (wall = fibrous/granulation tissue), typically forming 4-6 weeks after acute pancreatitis from ductal disruption. True cyst: has an epithelial lining (e.g., serous cystadenoma, mucinous cystic neoplasm, IPMN)."]','A','Most pseudocysts (>50%) resolve spontaneously within 6 weeks. Large, enlarging, symptomatic, or infected pseudocysts require drainage (endoscopic, radiological, or surgical). Amylase levels in pseudocyst fluid are very high. Pseudocysts must be distinguished from cystic neoplasms (which require resection) by imaging characteristics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17/18: Acute Pancreatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Pancreatic Disease','medium','flashcard','What are the consequences of chronic pancreatitis on exocrine and endocrine function?','["Exocrine insufficiency (>90% acinar destruction): steatorrhoea (lipase deficiency), fat-soluble vitamin (A, D, E, K) deficiency, protein maldigestion. Endocrine insufficiency: pancreatogenic (type 3c) diabetes from islet destruction — brittle diabetes, increased risk of hypoglycaemia (glucagon also lost)."]','A','Pancreatogenic diabetes differs from type 1 and type 2 DM: islet cell destruction affects both beta cells (insulin) and alpha cells (glucagon), producing brittle, unpredictable glycaemic control with high hypoglycaemia risk. Enzyme replacement therapy (PERT — pancreatic enzyme replacement therapy) is the mainstay of exocrine insufficiency management.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17/18: Chronic Pancreatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Pancreatic Disease','hard','flashcard','What is IPMN and how does the malignant potential of main duct IPMN differ from branch duct IPMN?','["Intraductal papillary mucinous neoplasm (IPMN): mucin-secreting papillary neoplasm of pancreatic duct epithelium. Main duct IPMN (MPD dilated >5 mm): ~70% risk of high-grade dysplasia or invasive carcinoma → surgical resection indicated. Branch duct IPMN: ~25% malignant risk; surveillance if <3 cm without worrisome features."]','A','Worrisome features of branch duct IPMN warranting surgical consideration: size >3 cm, presence of mural nodule, thickened/enhancing walls, main duct dilatation 5-9 mm, abrupt change in duct calibre, regional lymphadenopathy. High-risk features (main duct >10 mm, enhancing mural nodule, obstructive jaundice) mandate resection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17/18: IPMN, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Pancreatic Disease','easy','flashcard','What radiological finding on plain abdominal X-ray is characteristic of chronic pancreatitis?','["Pancreatic calcification — stippled or irregular calcification in the pancreatic area, representing calcium carbonate precipitation within protein plugs in chronically obstructed pancreatic ducts. Most commonly associated with alcoholic chronic pancreatitis."]','A','Pancreatic calcification is pathognomonic of chronic pancreatitis on plain X-ray. CT scanning is more sensitive and also shows pancreatic duct dilatation, pancreatic atrophy, and complications such as pseudocysts. MRCP (with secretin) best assesses ductal anatomy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17/18: Chronic Pancreatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Pancreatic Disease','medium','flashcard','What is hereditary pancreatitis and what is the causative mutation?','["Hereditary pancreatitis: autosomal dominant condition caused by gain-of-function PRSS1 (cationic trypsinogen) mutations that prevent trypsin auto-inactivation; causes recurrent acute pancreatitis from childhood with 40-70% lifetime risk of pancreatic ductal adenocarcinoma by age 70."]','A','PRSS1 gain-of-function mutations allow trypsinogen to resist autolysis by trypsin (which normally prevents premature activation). This leads to recurrent episodes of intrapancreatic trypsin activation, progressive destruction of the exocrine pancreas, and a greatly elevated cancer risk. Surveillance by MRI/MRCP is recommended from age 40.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17/18: Pancreatitis, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Pancreatic Disease','hard','flashcard','What tumour marker is elevated in pancreatic cancer and what are the molecular drivers of pancreatic ductal adenocarcinoma?','["CA 19-9 elevated in ~80% (not specific — also elevated in biliary obstruction). Molecular drivers: KRAS mutation (>90% — initiating event in PanIN), CDKN2A/p16 loss, SMAD4 loss, TP53 mutation. Somatic BRCA2 mutations (10%) and germline BRCA2 confer hereditary risk."]','A','The progression from PanIN-1 (flat and papillary low-grade) to PanIN-3 (carcinoma in situ) to invasive ductal adenocarcinoma is driven by sequential acquisition of KRAS, CDKN2A, SMAD4, and TP53 alterations. KRAS inhibitors (sotorasib, adagrasib) now have emerging applications. BRCA-mutated pancreatic cancer may respond to PARP inhibitors and platinum-based chemotherapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17/18: Pancreatic Carcinoma, p.836'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Appendicitis and Peritonitis','easy','flashcard','What is Rovsing''s sign and what does it indicate?','["Rovsing''s sign: palpation of the left iliac fossa produces referred pain in the right iliac fossa, indicating peritoneal irritation from an inflamed appendix. It is a supportive (not diagnostic) sign of acute appendicitis."]','A','The peritoneum over the appendix is irritated by inflammation, causing referred pain when pressure is applied at a distance. Other appendicitis signs: psoas sign (right hip hyperextension causes pain — suggests retrocaecal appendix), obturator sign (internal rotation of flexed right hip causes pain — suggests pelvic appendix).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Acute Appendicitis, p.816'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Appendicitis and Peritonitis','medium','flashcard','List the components of the Alvarado score (MANTRELS) for acute appendicitis.','["M: Migration of pain to RIF (1 point). A: Anorexia (1). N: Nausea/Vomiting (1). T: Tenderness in RIF (2). R: Rebound tenderness (1). E: Elevated temperature >37.3°C (1). L: Leukocytosis >10,000/μL (2). S: Shift to left/neutrophilia (1). Total: 10 points. Score ≥7 = high probability; 5-6 = equivocal; ≤4 = low probability."]','A','The Alvarado score (1986) aids clinical decision-making but should not replace clinical judgement. In equivocal cases (score 5-6), CT abdomen/pelvis (most accurate, sensitivity >95%) or USS is recommended. CT is preferred over USS in adults; USS preferred in children and pregnant women to avoid radiation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Acute Appendicitis, p.816'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Appendicitis and Peritonitis','medium','flashcard','What is the histological criterion for diagnosing acute appendicitis?','["Neutrophilic infiltration of the muscularis propria of the appendix wall. Mucosal neutrophilia alone is insufficient (can occur in other conditions). Gangrenous appendicitis shows transmural neutrophilic infiltration with vascular thrombosis and necrosis."]','A','Histological examination of the resected appendix is mandatory even when the diagnosis appears clinically clear, because incidental findings (e.g., carcinoid tumour, Crohn''s disease, endometriosis) may be discovered. The gross appearance of a normal appendix should not dissuade histological examination if clinical features are compelling.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Acute Appendicitis, p.816'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Appendicitis and Peritonitis','easy','flashcard','What is the most common cause of appendiceal luminal obstruction in adults leading to acute appendicitis?','["Faecolith (appendicolith) — a calcified faecal concretion obstructing the appendiceal lumen, causing bacterial overgrowth, raised intraluminal pressure, mucosal ischaemia, and acute appendicitis. In children, lymphoid follicle hyperplasia is a more common cause."]','A','Appendiceal faecoliths are visible on plain X-ray in ~10% of cases and on CT in ~25-30%. Their presence on CT in a patient with right iliac fossa pain increases the likelihood of appendicitis. Appendiceal obstruction leads to a cycle of increasing intraluminal pressure, ischaemia, bacterial invasion, and inflammatory necrosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Acute Appendicitis, p.816'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Appendicitis and Peritonitis','hard','flashcard','What are the complications of acute appendicitis and how do they arise?','["1. Perforation → peritonitis (generalised faecal peritonitis if free perforation). 2. Peri-appendiceal abscess (localised perforation walled off by omentum and bowel). 3. Pylephlebitis (septic portal vein thrombosis — rare, life-threatening). 4. Psoas abscess. 5. Bowel obstruction from adhesions."]','A','Perforation rates are highest at extremes of age (children <5 years, elderly) who present late or atypically. A ''missed appendicitis'' or delayed diagnosis is a major cause of morbidity. Perforation rates in pregnant women are high (30-40%) due to displacement of the appendix and non-specific symptoms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Acute Appendicitis, p.816'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Appendicitis and Peritonitis','easy','flashcard','What is pseudomyxoma peritonei and from which tumour does it most commonly arise?','["Pseudomyxoma peritonei: widespread accumulation of gelatinous mucinous material throughout the peritoneal cavity, most commonly arising from rupture of a low-grade appendiceal mucinous neoplasm (LAMN); treated with cytoreductive surgery + HIPEC."]','A','LAMN is a non-invasive mucinous neoplasm of the appendix that can produce large volumes of mucin. If the appendix perforates, mucin and neoplastic cells distribute along peritoneal surfaces (''redistribution phenomenon''). Right diaphragm, liver, spleen, and pelvic organs are typically involved. ''Jelly belly'' is a colloquial term for advanced pseudomyxoma peritonei.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Tumors of the Appendix, p.816'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Appendicitis and Peritonitis','medium','flashcard','What are the features of secondary peritonitis and how does it differ from primary peritonitis?','["Secondary peritonitis: caused by intra-abdominal source (perforated appendix, perforated peptic ulcer, bowel perforation, anastomotic leak) — polymicrobial (Gram-negatives + anaerobes). Primary peritonitis: no intra-abdominal source — monomicrobial (E. coli or Klebsiella in cirrhotic SBP; Streptococcus pneumoniae in children)."]','A','Secondary peritonitis produces a rigid abdomen (''board-like''), absent bowel sounds, and signs of systemic sepsis. Treatment requires surgical intervention (source control) plus broad-spectrum antibiotics. Primary peritonitis (SBP in cirrhosis) is treated medically without surgery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Peritoneal Infection, p.817'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Appendicitis and Peritonitis','easy','flashcard','What is the most common tumour of the appendix and what is its malignant potential?','["Carcinoid tumour (well-differentiated neuroendocrine tumour, NET): most common appendiceal tumour, typically at the appendiceal tip, usually <2 cm. Metastasis risk: rare if <2 cm (~2%), significant if >2 cm (~30%). Carcinoid syndrome (flushing, diarrhoea) occurs only with hepatic metastases."]','A','Appendiceal NETs are often discovered incidentally at appendicectomy for presumed appendicitis. Tumours <2 cm are treated adequately by appendicectomy. Tumours >2 cm or at the appendiceal base may require right hemicolectomy. Most appendiceal carcinoids are sporadic; occasional associations with MEN1 are reported.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Tumors of the Appendix, p.816'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Appendicitis and Peritonitis','hard','flashcard','What is pylephlebitis and why is it a complication of appendicitis?','["Pylephlebitis: septic thrombophlebitis of the portal vein and its tributaries, arising from direct spread of infection from the appendiceal/mesenteric venous drainage into the portal system; presents with fever, right upper quadrant pain, jaundice, and hepatic abscesses."]','A','Pylephlebitis is a rare but life-threatening complication of appendicitis, diverticulitis, or other intra-abdominal infections drained by the portal system. The appendiceal vein drains into the ileocolic vein → superior mesenteric vein → portal vein. Septic emboli may seed the liver, causing multiple pyogenic abscesses. Treatment: antibiotics (prolonged) ± anticoagulation.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Acute Appendicitis, p.816'),
('{"medicine"}','Medicine','Gastroenterology','Pathology','Appendicitis and Peritonitis','medium','flashcard','What is the psoas sign and obturator sign in the clinical examination of suspected appendicitis?','["Psoas sign: pain on passive extension of the right hip with the patient in left lateral decubitus position — suggests a retrocaecal appendix irritating the psoas muscle. Obturator sign: pain on passive internal rotation of the flexed right hip — suggests a pelvic appendix irritating the obturator internus muscle."]','A','These positional signs help localise an inflamed appendix. A retrocaecal appendix (most common anatomical variant, ~65%) may produce a positive psoas sign without classic McBurney''s tenderness. A pelvic appendix may mimic right adnexal pathology in women, requiring pelvic USS or CT for clarification.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease, 9th Ed, Ch 17: Acute Appendicitis, p.816');
